from datetime import datetime, timezone
from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import write_off
from ledgerly.errors import BillingError
from ledgerly.models import Invoice, LineItem

at = datetime(2026,2,1,tzinfo=timezone.utc)
def inv(status="issued"):
    return Invoice("inv_1","cus_1",lines=[LineItem("Seat",2,Decimal("25.00"))],status=status)

# non-issued rejected
for s in ("draft","paid","void"):
    try:
        write_off(inv(s), at, "x"); print("FAIL", s)
    except BillingError as e: print("ok reject", s, e.code)

# idempotency
i = inv()
r1 = write_off(i, at, "insolvent", idempotency_key="k1")
r2 = write_off(i, at, "insolvent", idempotency_key="k1")
print(r1, r2, len(audit.events("invoice_written_off")))

# reason too long
try:
    write_off(inv(), at, "x"*201); print("FAIL long")
except BillingError as e: print("ok long", e.code)
print("ok 200:", write_off(inv(), at, "x"*200)["reason"][:3])
